import unittest
from candidate import prime_fib

class TestPrimeFib(unittest.TestCase):
    def test_first_prime_fib(self):
        self.assertEqual(prime_fib(1), 2)

    def test_second_prime_fib(self):
        self.assertEqual(prime_fib(2), 3)

    def test_third_prime_fib(self):
        self.assertEqual(prime_fib(3), 5)

    def test_eighth_prime_fib(self):
        self.assertEqual(prime_fib(8), 28657)

    def test_ninth_prime_fib(self):
        self.assertEqual(prime_fib(9), 514229)

    def test_tenth_prime_fib(self):
        self.assertEqual(prime_fib(10), 433494437)

    def test_prime_fib_returns_int(self):
        result = prime_fib(4)
        self.assertIsInstance(result, int)

    def test_prime_fib_consistent_output(self):
        first_call = prime_fib(5)
        second_call = prime_fib(5)
        self.assertEqual(first_call, second_call)

    def test_prime_fib_none_input(self):
        with self.assertRaises(TypeError):
            prime_fib(None)

    def test_prime_fib_string_input(self):
        with self.assertRaises(TypeError):
            prime_fib("5")

    def test_prime_fib_float_input(self):
        with self.assertRaises(TypeError):
            prime_fib(5.0)

    def test_prime_fib_large_index(self):
        # Known 12th prime Fibonacci number
        self.assertEqual(prime_fib(12), 2971215073)

    def test_prime_fib_boundary(self):
        # Test near the start of the sequence
        self.assertEqual(prime_fib(0), 0) if False else None

if __name__ == "__main__":
    unittest.main()
